// Hand-written `zod` stub for the flowatlas fixture suite.
//
// Only what makes a schema's `parse` hand back a typed value: a schema carries
// the type it checks for, and an object schema's is built from its fields'.

export interface ZodType<Output = unknown> {
  readonly _output: Output;
  parse(data: unknown): Output;
  parseAsync(data: unknown): Promise<Output>;
  optional(): ZodType<Output | undefined>;
}

type Shape = Record<string, ZodType<any>>;

export interface ZodObject<S extends Shape> extends ZodType<{ [K in keyof S]: S[K]['_output'] }> {}

export declare const z: {
  object<S extends Shape>(shape: S): ZodObject<S>;
  string(): ZodType<string>;
  number(): ZodType<number>;
  boolean(): ZodType<boolean>;
};
